  "etudes.hammerOnHPickTheFirstNoteThenPressAHigherFret": "Hammer-on (H): Pick the first note, then press a higher fret on the same string to sound the second. Keep both notes at a similar volume.",
  "etudes.pullOffPFretTheLowerNoteInAdvanceGentlyPullThe": "Pull-off (P): Fret the lower note in advance. Gently pull the higher finger off the string to sound it; do not pick the destination note again.",
  "etudes.slideSlPickTheFirstNoteThenKeepTheSameFingerOn": "Slide (SL): Pick the first note, then keep the same finger on the string as you move to the destination fret. Arrive on the indicated beat.",
  "etudes.beginnerFocusOnQuarterAndEighthNoteLengthsAndConnectingShortPatterns": "Beginner · Focus on quarter- and eighth-note lengths and connecting short patterns.",
