  "etudes.beginnerSteadyEighthNotesAndChromaticMovementWithinASmallPositionThe": "Beginner · Steady eighth notes and chromatic movement within a small position. The blues label does not imply a higher difficulty.",
  "etudes.intermediateControlPositionShiftsAcrossStringsAndTheTimingOfSlideArrivals": "Intermediate · Control position shifts across strings and the timing of slide arrivals.",
