  "etudes.intermediateFocusOnLeapsBetween1357AndPositionShifts": "Intermediate · Focus on leaps between 1·3·5·7 and position shifts. This single major-seventh pattern is not an advanced jazz improvisation exercise.",
  "etudes.intermediateSwitchBetweenHammerOnsPullOffsAndSlidesInEighthNotes": "Intermediate · Switch between hammer-ons, pull-offs, and slides in eighth notes. Techniques are combined, but speed and rhythm demands remain moderate.",
  "etudes.advancedTheUpperLevelOfThisCurriculumSustainContinuousSixteenthNotesAt": "Advanced · The upper level of this curriculum. Sustain continuous sixteenth notes at 80 BPM (about 5.3 notes per second) for eight bars while changing position and direction.",
  "etudes.learnTwoBarsAtATimeThenConnectFourAndEightBars": "Learn two bars at a time, then connect four and eight bars. Listen for where a pattern repeats and where it changes.",
  "etudes.bars13IntroduceThePatternBars47VaryItsRange": "Bars 1–3 introduce the pattern, bars 4–7 vary its range and shape, and bar 8 resolves to the tonic. Learn each section, then connect all eight bars.",
  "etudes.playVerticallyStackedTabNumbersTogetherUseYourThumbPForBass": "Play vertically stacked TAB numbers together. Use your thumb (p) for bass and index (i), middle (m), and ring (a) fingers for strings 3, 2, and 1. Hold each chord shape to let notes ring together; mute previous notes at rests or chord changes.",
  "etudes.thisIsALeadGuitarChordToneExercisePlayOneNoteAt": "This is a lead-guitar chord-tone exercise. Play one note at a time and lightly mute strings after leaving them. For accompaniment that holds chord shapes while plucking bass and treble together, use the arpeggio course.",
  "etudes.pickUnmarkedNotesRepeatOneBarAtATimeThenConnectBars": "Pick unmarked notes. Repeat one bar at a time, then connect bars once the rhythm is steady.",
  "etudes.chordDiagramsShowStrings16FromTopToBottomWithHigher": "Chord diagrams show strings 1–6 from top to bottom, with higher frets to the right. × means do not play; ○ means open string; a thick vertical line is a barre; fr below indicates the starting fret. Circled 1·2·3·4 mean index, middle, ring, and little finger. Hold the chord shape instead of moving a finger for every note on the same fret.",
  "etudes.suggestedStartingTempoValueBpmStartSlowlyAndCheckThatVolumeAnd": "Suggested starting tempo: {value1} BPM. Start slowly and check that volume and timing remain even.",
  "etudes.afterThreeUninterruptedRunsAtTheSameTempoTryIncreasingBy4": "After three uninterrupted runs at the same tempo, try increasing by 4 BPM. Rest and reduce tension if your hand becomes uncomfortable.",
  "etudes.valueFromString1AtTheTopValue": "{value1}, from string 1 at the top: {value2}",
