  "etudes.threeTechniqueLegato": "Three-Technique Legato",
  "etudes.connectConsecutiveNotesOnTheSameStringWithHPAndSl": "Connect consecutive notes on the same string with H, P, and SL. Pick again when changing strings and keep each note at an even volume.",
  "etudes.sustainTechniqueChangesStringChangesAndPositionShiftsInSixteenthNotes": "Sustain technique changes, string changes, and position shifts in sixteenth notes.",
  "etudes.sequencesAndLeapsCompleteSolo": "Sequences and Leaps: Complete Solo",
  "etudes.connectStepwiseMotionThirdsFourthsAndPivotPatternsIntoOnePhraseHear": "Connect stepwise motion, thirds, fourths, and pivot patterns into one phrase. Hear the first beat of each new pattern and resolve to the final tonic.",
  "etudes.advancedSynthesisMaintainAFastRhythmWhileChangingTheIntervalPatternIn": "Advanced synthesis: Maintain a fast rhythm while changing the interval pattern in each bar.",
  "etudes.connectStringsOneBeatAtATime": "Connect Strings One Beat at a Time",
  "etudes.useEighthNotesOnJustOneBeatInBars14Then": "Use eighth notes on just one beat in bars 1–4, then descend in bars 5–8. Release tension on the long note after changing strings.",
  "etudes.twoStringRoundTripToTheRoot": "Two-String Round Trip to the Root",
  "etudes.connectTwoNotesOnOneBeatToALongDestinationNoteCheck": "Connect two notes on one beat to a long destination note. Check the final A in bars 1, 6, 7, and 8, and mute strings you have left.",
  "etudes.pentatonicStringSkippingResponse": "Pentatonic String-Skipping Response",
  "etudes.skipStringsInTwoNoteGroupsInBars14ThenAlternate": "Skip strings in two-note groups in bars 1–4, then alternate single notes in bars 5–6. Use both hands to mute skipped strings.",
  "etudes.offbeatsWithStringSkipping": "Offbeats with String Skipping",
  "etudes.connectAnOpeningRestAndSixteenthNoteLeapsToALongNote": "Connect an opening rest and sixteenth-note leaps to a long note. Leave the first half-beat empty in bars 1, 2, 5, and 6, and keep the volume even after string skips.",
  "etudes.distinguishCAndAmChordTones": "Distinguish C and Am Chord Tones",
  "etudes.distinguishCEGInBars135And7From": "Distinguish C–E–G in bars 1, 3, 5, and 7 from A–C–E in bars 2, 4, and 6. Return to C in bar 8. Separate each note rather than holding a ringing accompaniment chord.",
  "etudes.connectThirdsAndSevenths": "Connect Thirds and Sevenths",
  "etudes.connectThe3rdsAnd7thsOfDm7G7Cmaj7PrepareFB": "Connect the 3rds and 7ths of Dm7→G7→Cmaj7. Prepare F→B from bars 1→2 and B→E from bars 2→3. In bars 5–8, change the starting note while tracing the same harmony. Mute the intervening strings when moving up an octave from E at string 5, fret 7 at the end of bar 7 to E at string 2, fret 5 at the start of bar 8.",
  "etudes.hammerOnAndPullOffResponse": "Hammer-on and Pull-off Response",
  "etudes.applyHHPToTheFirstFourNotesOfBars1": "Apply H–H–P to the first four notes of bars 1–7, using the short response you learned earlier. Pick only the first note and rest on the last beat to hear the phrase end.",
  "etudes.comparePickedAndValueNoteVolume": "Compare Picked and {value1} Note Volume",
  "etudes.pickOnBeat1AndUseValueForTheTwoNotesOn": "Pick on beat 1 and use {value1} for the two notes on beat 2. Move to string 2 in bars 3–4, keep the volume even, and hold the final half note for its full length.",
  "etudes.valueWithAMidBarStringChange": "{value1} with a Mid-Bar String Change",
  "etudes.changeStringsOnBeat3InBars12PracticePickingThe": "Change strings on beat 3. In bars 1–2, practice picking the first note on the new string separately from muting the previous string.",
  "etudes.valueControlDensityAndArrival": "{value1}: Control Density and Arrival",
  "etudes.connectTheFourNotesOnBeat1WithValueChangeStringsOn": "Connect the four notes on beat 1 with {value1}, change strings on beat 2, and sustain through beats 3–4. Control the destination note's length and volume independently of the fast run.",
  "etudes.landOnTargetNotesAtChordChanges": "Land on Target Notes at Chord Changes",
  "etudes.developAMotifThroughTheHarmony": "Develop a Motif through the Harmony",
  "etudes.targetNotesRestsAndLegatoMiniSolo": "Target Notes, Rests, and Legato Mini Solo",
  "etudes.endEachBarOnALongChordToneFirstPracticeTheE": "End each bar on a long chord tone. First practice the E/A/A/G arrivals in bars 1–4 and C/A/F/C in bars 5–8 separately.",
  "etudes.reorderBar1SAscendingMotifInBar2ThenAdaptIt": "Reorder bar 1's ascending motif in bar 2, then adapt it to the harmony in bars 3–4. Change register in bars 5–8 before returning to the original motif.",
  "etudes.combineIntermediateOffbeatsHPAndTwoPositionsWithinEightBarsAnswer": "Combine intermediate offbeats, H/P, and two positions within eight bars. Answer after rests in bars 2 and 4, then return to long notes after the short sixteenth-note run in bar 5.",
  "etudes.advancedPrioritizeHarmonicArrivalsMotifContinuityRhythmAndExpressionAlongsideSpeed": "Advanced · Prioritize harmonic arrivals, motif continuity, rhythm, and expression alongside speed.",
  "etudes.warmUpbeatMelodicFingerstyleWithASenseOfForwardMotion40Written": "Warm, upbeat melodic fingerstyle with a sense of forward motion. 40 written bars, 56 with repeats. Listen to the short melodies and simultaneously plucked chords, then make your own variations.",
  "etudes.playStackedTabNumbersTogetherAlternateBassAndMelodyPinchesMiddleVoice": "Play stacked TAB numbers together. Alternate bass-and-melody pinches, middle-voice dyads, and single-note responses. Avoid emphasizing strums or country-style alternating bass.",
  "etudes.letTheLongNotesOnStrings1And2SingAndPlay": "Let the long notes on strings 1 and 2 sing, and play the inner sixteenths softly. Make the D# and A in B7 and the G# and D in E7 clear.",
  "etudes.theBassInBars2324DescendsAGFEBars": "The bass in bars 23–24 descends A→G→F→E. Bars 29–36 open up the register with small barres and partial voicings at frets 5–10. Use a partial voicing for G's high B.",
  "etudes.thePreChorusIsCondensedToTwoBarsInItsFinalBar": "The pre-chorus is condensed to two bars. In its final bar, Em7, Am7, and Dm7 each last one beat; Gsus4 and G each last half a beat. The first and second pre-choruses use different rhythms.",
  "etudes.listenForGsus4GOnBeat3OfBar39AndC": "Listen for Gsus4→G on beat 3 of bar 39 and C→E/G→D/E in the final Cadd9. Let the final two beats ring without picking again. Keep 92 BPM to the end.",
  "etudes.intermediateConnectBassAndTrebleMelodyWithMixedRhythmsAndPositionShifts": "Intermediate · Connect bass and treble melody with mixed rhythms and position shifts.",
  "etudes.fingerstyle": "Fingerstyle",
  "etudes.startAfterLearningOpenChordsSmallBarresAndSimultaneousBassAndTreble": "Start after learning open chords, small barres, and simultaneous bass-and-treble plucking.",
