  "etudes.bringOutTheTrebleMelodyWhileGentlyPluckingTheInnerDyads": "Bring out the treble melody while gently plucking the inner dyads.",
  "etudes.aSketchForCompositionInspirationAdjustFingeringAndDynamicsToSuitYour": "A sketch for composition inspiration · Adjust fingering and dynamics to suit your own guitar playing.",
