  "etudes.steadyEighthNotes": "Steady eighth notes",
  "etudes.steadySixteenthNotes": "Steady sixteenth notes",
  "etudes.enterAfterAnEighthRest": "Enter after an eighth rest",
  "etudes.restUDU": "Rest U D U",
  "etudes.beginnerQuarterNotes": "Beginner · Quarter notes",
  "etudes.intermediateEighthNotes": "Intermediate · Eighth notes",
  "etudes.advancedFourSubdivisionsOnBeat1": "Advanced · Four subdivisions on beat 1",
  "etudes.setTheChordShapeFirst": "Set the chord shape first",
  "etudes.followTheChordDiagramAboveTheBarAndHoldYourFingersIn": "Follow the chord diagram above the bar and hold your fingers in place. Unlike single-note exercises, do not re-fret and move your left hand for each note. Use only the strings shown in the exercise's chord diagram.",
  "etudes.pluckStackedNumbersTogether": "Pluck stacked numbers together",
  "etudes.tabNumbersStackedVerticallyAtTheSameHorizontalPositionSoundTogetherStart": "TAB numbers stacked vertically at the same horizontal position sound together. Start the bass and treble fingers at the same time rather than brushing across them in sequence.",
  "etudes.giveTheThumbAndTrebleFingersSeparateRoles": "Give the thumb and treble fingers separate roles",
  "etudes.pMeansThumbIIndexMMiddleAndARingFingerStart": "p means thumb, i index, m middle, and a ring finger. Start with the thumb on bass strings 6, 5, and 4, and index, middle, and ring fingers on strings 3, 2, and 1. p+m means pluck with thumb and middle finger together.",
  "etudes.letNotesRingWithinTheSameChord": "Let notes ring within the same chord",
  "etudes.letRingMeansAllowingEarlierNotesToOverlapNaturallyWithTheNext": "Let ring means allowing earlier notes to overlap naturally with the next notes. Do not lift your fretting hand immediately or stop a ringing string with the next finger. At a chord change, mute any unwanted resonance from the previous chord.",
  "etudes.distinguishRootAndFifthInTheBass": "Distinguish root and fifth in the bass",
  "etudes.theLowestNoteOnBeat1IsTheRootOfThatBar": "The lowest note on beat 1 is the root of that bar's chord. Alternating-bass exercises use the fifth on beat 3. Listen to the thumb supporting the beat while the treble flows above it.",
  "etudes.muteTogetherAtRests": "Mute together at rests",
  "etudes.atRestsInThisIntroductoryScoreLightlyMuteTheRingingStringsAnd": "At rests in this introductory score, lightly mute the ringing strings and prepare the next chord. Keep counting internally after the sound stops. You can also practice chord changes separately.",
  "etudes.balanceSimultaneousAndSeparateNotes": "Balance simultaneous and separate notes",
  "etudes.doNotPullHardWhenPluckingSeveralNotesTogetherKeepTheThumb": "Do not pull hard when plucking several notes together. Keep the thumb from overpowering the treble and start at a slow BPM where the chord stays clear. Relax your hands and rest if uncomfortable.",
  "etudes.downAndUpDescribePickDirectionNotPitch": "Down and up describe pick direction, not pitch",
  "etudes.dDownMovesFromString6TowardString1UUpMoves": "D (down) moves from string 6 toward string 1; U (up) moves the other way. A rising melody does not require upstrokes. Alternating D–U–D–U on evenly spaced notes is called alternate picking.",
  "etudes.tryStartingWithADownstroke": "Try starting with a downstroke",
  "etudes.startingContinuousEighthsOrSixteenthsWithADownstrokeGivesPracticeAClear": "Starting continuous eighths or sixteenths with a downstroke gives practice a clear reference. Do not restart with a downstroke at every string change. Practicing from an upstroke is also useful; no single direction is right for all music.",
  "etudes.restsOccupySubdivisionsToo": "Rests occupy subdivisions too",
  "etudes.theChartBelowDemonstratesPickingDirectionsAlignedWithSteadySubdivisionsInEighth": "The chart below demonstrates picking directions aligned with steady subdivisions. In eighth notes, resting on the first subdivision means entering with an upstroke on the next &. Count through the silence. With mixed long notes and rests, do not assign D/U solely by counting the sounding notes.",
  "etudes.doNotPickAgainAtHPOrSl": "Do not pick again at H, P, or SL",
  "etudes.inThisScoreTheDestinationNotesOfHHammerOnPPull": "In this score, the destination notes of H (hammer-on), P (pull-off), and SL (legato slide) are sounded by the fretting hand. Pick the first note of each connected group, then resume when changing strings or after the connection ends. Do not force down/up strokes onto destination notes.",
  "etudes.evenLengthAndVolumeBeforeSpeed": "Even length and volume before speed",
  "etudes.keepThePickShallowAgainstTheStringAndUseOnlyTheMovement": "Keep the pick shallow against the string and use only the movement you need. Listen for an even sound between downstrokes and upstrokes, and lightly mute unwanted strings with both hands. Chord-accompaniment exercises let earlier notes overlap, so follow their specific tips. Relax your shoulders and hands, and stop to rest if uncomfortable.",
  "etudes.restsAndLongNotesShapeThePhrase": "Rests and long notes shape the phrase",
  "etudes.afterShortNotesHoldLongNotesForTheirWrittenDurationAndStop": "After short notes, hold long notes for their written duration and stop the sound at rests. Hear two bars as a call and response. Shape the beginning and end of each phrase rather than striking every note hard.",
  "etudes.practiceDifficultTransitionsSeparately": "Practice difficult transitions separately",
  "etudes.slowlyRepeatTheTwoToFourNotesAroundAMistakeThenReconnect": "Slowly repeat the two to four notes around a mistake, then reconnect one bar, two bars, and the full piece. Raise BPM gradually once note and rest lengths, muting, and technique arrivals are stable.",
